# Hybrid fan-out: push for normal authors, pull for celebrities.
THRESHOLD = 3                      # followers above this = celebrity (toy value)
followers = {"ann": ["u1", "u2"], "star": ["u1", "u2", "u3", "u4", "u5"]}
follows = {"u1": ["ann", "star"], "u2": ["star"]}
timeline = {}                      # precomputed lists (push)
posts = {"ann": [], "star": []}    # author's own recent posts

def post(author, pid):
    posts[author].append(pid)
    if len(followers[author]) <= THRESHOLD:
        for f in followers[author]:           # fan-out on write
            timeline.setdefault(f, []).append(pid)
        return "pushed to %d timelines" % len(followers[author])
    return "celebrity: stored once, no fan-out"

def read_feed(user):
    feed = list(timeline.get(user, []))       # cheap cache read
    for a in follows.get(user, []):
        if len(followers[a]) > THRESHOLD:     # merge celebrities at read time
            feed += posts[a]
    return sorted(feed)

print(post("ann", "p1"))
print(post("star", "p2"))
print(post("ann", "p3"))
print("u1 feed:", read_feed("u1"))
print("u2 feed:", read_feed("u2"))

# Optimistic commit: compare-and-swap on the base version, keep both on conflict.
meta = {"version": 1, "content": "base"}
files = {"report.txt": dict(meta)}

def commit(name, base_version, content):
    cur = files[name]
    if cur["version"] != base_version:       # someone committed first
        conflict = name.replace(".txt", " (conflicted copy).txt")
        files[conflict] = {"version": 1, "content": content}
        return "conflict -> saved as " + conflict
    files[name] = {"version": base_version + 1, "content": content}
    return "ok, now version %d" % (base_version + 1)

print("both devices start from version 1")
print("laptop:", commit("report.txt", 1, "laptop edit"))
print("phone :", commit("report.txt", 1, "phone edit"))
